const shown = (c: Conjugated) => (c.ok ? c.jp : "—");

describe("conjugateVerb: full golden tables", () => {
  it.each(FULL)("%s (%s)", (dict, cls, table) => {
    const expected = table.split(" · ");
    expect(expected).toHaveLength(VERB_FORMS.length);
    const got = VERB_FORMS.map(({ form }) => shown(conjugateVerb(dict, cls, form)));
    expect(Object.fromEntries(VERB_FORMS.map(({ form }, i) => [form, got[i]]))).toEqual(
      Object.fromEntries(VERB_FORMS.map(({ form }, i) => [form, expected[i]])),
    );
  });
});

describe("conjugateVerb: exceptions and compounds", () => {
  it.each(PARTIAL)("%s (%s)", (dict, cls, forms) => {
    for (const [form, want] of Object.entries(forms)) {
      expect(shown(conjugateVerb(dict, cls, form as VerbForm)), `${dict} ${form}`).toBe(want);
    }
  });

  it("gives a reason for every form a verb lacks", () => {
    const r = conjugateVerb("ある", "godan", "potential");
    expect(r.ok).toBe(false);
    expect(!r.ok && r.reason).toMatch(/potential/);
  });

  it("offers せよ as the written variant of しろ", () => {
    expect(conjugateVerb("する", "suru", "imperative")).toEqual({ ok: true, jp: "しろ", variants: ["せよ"] });
  });

  it("accepts the plain negative + です as a polite negative", () => {
    expect(conjugateVerb("[食|た]べる", "ichidan", "politeNeg")).toMatchObject({ jp: "[食|た]べません", variants: ["[食|た]べない です"] });
    expect(conjugateVerb("ある", "godan", "politePastNeg")).toMatchObject({ jp: "ありません でした", variants: ["なかった です"] });
  });

  it("keeps the ら-less potential apart, as colloquial", () => {
    expect(conjugateVerb("[食|た]べる", "ichidan", "potential")).toMatchObject({ jp: "[食|た]べられる", variants: [], colloquial: ["[食|た]べれる"] });
    expect(conjugateVerb("[来|く]る", "kuru", "potential")).toMatchObject({ colloquial: ["[来|こ]れる"] });
    expect(conjugateVerb("[食|た]べる", "ichidan", "passive")).not.toHaveProperty("colloquial");
  });

  it("uses り before たい in honorific verbs, and marks their commands as polite", () => {
    expect(shown(conjugateVerb("おっしゃる", "godan", "tai"))).toBe("おっしゃりたい");
    expect(shown(conjugateVerb("なさる", "godan", "tai"))).toBe("なさりたい");
    expect(shown(conjugateVerb("くださる", "godan", "tai"))).toBe("—");
    expect(conjugateVerb("くださる", "godan", "imperative")).toMatchObject({ jp: "ください", note: expect.stringMatching(/polite/) });
    for (const form of ["potential", "volitional", "passive", "causative", "prohibitive"] as VerbForm[]) {
      expect(shown(conjugateVerb("おっしゃる", "godan", form)), form).toBe("—");
    }
    expect(conjugateVerb("いらっしゃる", "godan", "te")).toMatchObject({ jp: "いらっしゃって", variants: ["いらして"] });
  });

  it("refuses forms that できる, くれる and verbs of state don't have", () => {
    for (const form of ["tai", "passive", "causative", "prohibitive", "nasai", "teKudasai"] as VerbForm[]) {
      expect(shown(conjugateVerb("できる", "ichidan", form)), `できる ${form}`).toBe("—");
    }
    for (const form of ["tai", "potential", "volitional", "passive", "causative", "nasai", "teKudasai"] as VerbForm[]) {
      expect(shown(conjugateVerb("くれる", "ichidan", form)), `くれる ${form}`).toBe("—");
    }
    for (const dict of ["[見|み]える", "[聞|き]こえる"]) expect(shown(conjugateVerb(dict, "ichidan", "imperative")), dict).toBe("—");
    expect(shown(conjugateVerb("[要|い]る", "godan", "potential"))).toBe("—");
    expect(shown(conjugateVerb("[分|わ]かる", "godan", "nasai"))).toBe("—");
  });

  it("keys exceptions on the written form, not the reading", () => {
    expect(shown(conjugateVerb("[暮|く]れる", "ichidan", "imperative"))).toBe("[暮|く]れろ");
    expect(shown(conjugateVerb("いる", "ichidan", "potential"))).toBe("いられる");
  });

  it("keeps the noun of a one-word する compound, and refuses one-kanji する verbs", () => {
    expect(shown(conjugateVerb("[勉強|べんきょう]する", "suru", "polite"))).toBe("[勉強|べんきょう]します");
    expect(shown(conjugateVerb("[愛|あい]する", "suru", "plainNeg"))).toBe("—");
  });

  it("keeps whatever comes before 来る, and the show-kanji mark", () => {
    expect(shown(conjugateVerb("[持|も]って[来|く]る", "kuru", "plainNeg"))).toBe("[持|も]って[来|こ]ない");
    expect(shown(conjugateVerb("やって[来|く]る", "kuru", "polite"))).toBe("やって[来|き]ます");
    expect(shown(conjugateVerb("[!来|く]る", "kuru", "polite"))).toBe("[!来|き]ます");
  });

  it("reads kana 問う as とう, and refuses the classical ゆいて", () => {
    expect(shown(conjugateVerb("とう", "godan", "te"))).toBe("とうて");
    expect(shown(conjugateVerb("ゆく", "godan", "te"))).toBe("—");
  });
});

