describe("conjugateAdjective: golden tables", () => {
  it.each(ADJECTIVES)("%s (%s)", (dict, cls, table) => {
    const expected = table.split(" · ");
    expect(expected).toHaveLength(ADJECTIVE_FORMS.length);
    const got = ADJECTIVE_FORMS.map((form) => shown(conjugateAdjective(dict, cls, form)));
    expect(Object.fromEntries(ADJECTIVE_FORMS.map((form, i) => [form, got[i]]))).toEqual(
      Object.fromEntries(ADJECTIVE_FORMS.map((form, i) => [form, expected[i]])),
    );
  });

  it("conjugates only いい and its compounds from よ, not every adjective ending in いい", () => {
    expect(shown(conjugateAdjective("かわいい", "i", "plainNeg"))).toBe("かわいくない");
    expect(shown(conjugateAdjective("かわいい", "i", "plainPast"))).toBe("かわいかった");
    expect(shown(conjugateAdjective("[頭|あたま] が いい", "i", "plainNeg"))).toBe("[頭|あたま] が よくない");
    expect(shown(conjugateAdjective("ちょうどいい", "i", "te"))).toBe("ちょうどよくて");
    expect(shown(conjugateAdjective("[気持|きも]ちいい", "i", "plainNeg"))).toBe("[気持|きも]ちよくない");
    expect(shown(conjugateAdjective("[仲|なか]いい", "i", "plainPast"))).toBe("[仲|なか]よかった");
    expect(conjugateAdjective("いい", "i", "plain")).toEqual({ ok: true, jp: "いい", variants: ["よい"] });
  });

  it("lists the other correct ways to say a polite negative", () => {
    expect(conjugateAdjective("[高|たか]い", "i", "politeNeg")).toEqual({ ok: true, jp: "[高|たか]くない です", variants: ["[高|たか]く ありません"] });
    expect(conjugateAdjective("[静|しず]か", "na", "politeNeg")).toEqual({
      ok: true,
      jp: "[静|しず]か じゃ ありません",
      variants: ["[静|しず]か で は ありません", "[静|しず]か じゃ ない です", "[静|しず]か で は ない です"],
    });
  });
});
